mapper.select:
SELECT fc.figure_id, c.genre_character_id, c.name, g.genre_character_group_id, g.name AS genre_character_group_name FROM figure_character_map fc JOIN genre_character c ON c.user_id = fc.user_id AND c.genre_character_id = fc.genre_character_id JOIN genre_character_group g ON g.user_id = c.user_id AND g.genre_character_group_id = c.genre_character_group_id WHERE fc.user_id = #{userId} AND fc.figure_id IN
#{figureId}
ORDER BY fc.figure_id, c.genre_character_id
